export const PRICES=[1.79,2.19,2.59];
export const CHANNELS=['DTC Online','Retail/Grocery','Gym & Office'];
export function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if(c==='\n'&&!quoted){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw Error('Unclosed CSV quote');if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row);}const header=rows.shift();return rows.filter(r=>r.some(Boolean)).map(r=>{if(r.length!==header.length)throw Error('CSV column mismatch');return Object.fromEntries(header.map((h,i)=>[h,r[i]]));});}
export function validMix(weights){return weights.length===3&&weights.every(w=>Number.isFinite(w)&&w>=0&&w<=100)&&Math.abs(weights.reduce((a,b)=>a+b,0)-100)<1e-8;}
export function rowsAt(rows,price){if(!PRICES.includes(price))throw Error('Unsupported launch price');return CHANNELS.map(channel=>{const matches=rows.filter(r=>Number(r.price_eur)===price&&r.channel===channel);if(matches.length!==1)throw Error('Missing or duplicate price/channel record');return matches[0];});}
export function blend(rows,price,weights){if(!validMix(weights))return null;const selected=rowsAt(rows,price);const contribution=selected.reduce((s,r,i)=>s+Number(r.unit_contribution_eur)*weights[i]/100,0);const net=selected.reduce((s,r,i)=>s+Number(r.net_price_to_lumen_eur)*weights[i]/100,0);return{contribution,net,percent:contribution/net*100};}
